from solution import breakSum


def test_issue_example_12():
    """Example asserts breakSum(12) == 13."""
    assert breakSum(12) == 13  # 12//2=6, 12//3=4, 12//4=3, 6+4+3=13


def test_issue_zero():
    """Maximum sum for 0 stays 0."""
    assert breakSum(0) == 0  # max(0, 0+0+0)=0


def test_issue_one():
    """Maximum sum for 1 stays 1."""
    assert breakSum(1) == 1  # 0+0+0=0, max(1,0)=1


def test_issue_small_two():
    """Maximum sum for 2 stays 2 when splitting does not help."""
    assert breakSum(2) == 2  # 1+0+0=1, max(2,1)=2


def test_issue_below_threshold_eleven():
    """Maximum sum for 11 stays 11 just below the split threshold."""
    assert breakSum(11) == 11  # 5+3+2=10, max(11,10)=11


def test_issue_second_threshold_fifteen():
    """Maximum sum for 15 stays 15 just below the next split threshold."""
    assert breakSum(15) == 15  # 7+5+3=15, max(15,15)=15


def test_issue_above_threshold_sixteen():
    """Maximum sum for 16 is 17 just above the split threshold."""
    assert breakSum(16) == 17  # 8+5+4=17, max(16,17)=17


def test_issue_needs_recursion_twentyfour():
    """Maximum sum for 24 needs recursion through 12."""
    assert breakSum(24) == 27  # 13+8+6=27, max(24,27)=27


def test_issue_deep_recursion_fortyeight():
    """Maximum sum for 48 needs deep recursion."""
    assert breakSum(48) == 57  # 27+17+13=57, max(48,57)=57


def test_contract_result_is_int():
    """Result is an integer sum."""
    assert isinstance(breakSum(12), int)  # expected literal type int


def test_contract_never_less_than_input():
    """Maximum sum cannot be less than the number itself."""
    assert breakSum(24) >= 24  # 27>=24


def test_contract_repeatable():
    """Repeated calls return the same maximum sum."""
    assert breakSum(12) == breakSum(12)  # 13==13
